def total(prices, tax_rate):
    """Sum prices (pounds), apply tax, round to 2 decimals."""
    subtotal = 0
    for p in prices:
        subtotal += round(p * (1 + tax_rate), 2)
    return round(subtotal, 2)
import unittest
from price import total


class TestTotal(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(total([], 0.2), 0)

    def test_no_tax(self):
        self.assertEqual(total([1.50, 2.25], 0.0), 3.75)

    def test_simple_tax(self):
        self.assertEqual(total([10.00, 5.00], 0.2), 18.00)

    def test_tax_applied_to_sum(self):
        # 0.33 * 3 = 0.99; tax 10% -> 1.089 -> 1.09 (rounding once, at the end)
        self.assertEqual(total([0.33, 0.33, 0.33], 0.1), 1.09)


if __name__ == "__main__":
    unittest.main()
import unittest


class TestRounding(unittest.TestCase):
    def test_half_cent_rounds_up(self):
        self.assertEqual(round(1.005 + 0.0001, 2), 1.01)

    def test_half_cent_down_case(self):
        self.assertEqual(round(2.004, 2), 2.0)


if __name__ == "__main__":
    unittest.main()
